-- ============================================================================
-- V51__replace_busa_doc_mstr_seed_data.sql
--
-- Replaces all local BUSA_DOC_MSTR seed data with the rows supplied by
-- Sonny on 2026-05-04. The previous local seed (V22 sales rows
-- '1C25TWV-%' + V22 expense rows 'R-%' as corrected by V50) did not
-- match the live data Sonny wants the page to render, so the entire
-- table is wiped and reseeded.
--
-- Scope and safety
-- ----------------
--   * Only one BIZ_KEY exists in local BUSA_DOC_MSTR
--     ('VN_VNM0004_000001'). No FK references this table in the local
--     schema (V24 only added FKs OUTBOUND from BUSA_DOC_MSTR; child
--     tables BUSA_DOC_DETL / BUSA_DOC_DETL_HIS / BUSA_DOC_MSTR_HIS
--     are not yet in local Flyway). EINV_FEE_DETL / EINV_TAX_DETL /
--     BUSA_DOC_RCV_PAY_HIS hold rows referencing the previous DOC_IDs
--     but no FK enforces that link locally — they remain in place per
--     Sonny's instruction (BUSA_DOC_MSTR-only replacement).
--   * Constraint compliance verified before applying:
--       PK   (biz_key, doc_id)                  — all 25 DOC_IDs unique
--       UK01 (biz_key, reg_dt, seq_no)          — reg_dt + seq_no NULL
--                                                  on every row, so
--                                                  PostgreSQL's NULL-
--                                                  distinct semantics
--                                                  allow all 25
--       CHK01 doc_type ∈ ('I','B','E')          — every row 'I'
--       CHK02 pay_due_cd ∈ ('15','30','60','00') — every row '30'
--       CHK07 trco_trsc_ccy_cd ∈ ('VND','USD','999','998') or NULL
--                                                — every row 'VND' or
--                                                  NULL
--
-- INSERT statements below are reproduced verbatim from Sonny — no
-- value modified, no DOC_TYPE / HAND_REG_YN / ISSU_DT conversion.
-- ============================================================================

